from PIL import Image
import numpy as np
im=np.array(Image.open('first_frame.png').convert('RGB')); h,w,_=im.shape
R,G,B=im.transpose(2,0,1)
def comps(name,m,minn=20):
 seen=np.zeros((h,w),bool); out=[]
 for y,x in zip(*np.where(m)):
  if seen[y,x]:continue
  st=[(y,x)];seen[y,x]=1;n=0;xs=[];ys=[]
  while st:
   yy,xx=st.pop();n+=1;xs.append(xx);ys.append(yy)
   for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
    ny,nx=yy+dy,xx+dx
    if 0<=ny<h and 0<=nx<w and m[ny,nx] and not seen[ny,nx]:seen[ny,nx]=1;st.append((ny,nx))
  if n>=minn:out.append((n,min(xs),min(ys),max(xs),max(ys),np.mean(im[ys,xs],0).round(1)))
 print('\\n',name,'count',m.sum(),'comps')
 for q in sorted(out,reverse=True)[:20]:print(q)
comps('dark',(R<45)&(G<45)&(B<45),20)
comps('yellow',(R>70)&(G>60)&(R>B*1.5)&(G>B*1.3),20)
comps('blue',(B>R*1.25)&(B>G*1.05)&(B>45),20)
comps('brown',(R>G*1.05)&(G>B*1.05)&(R>45),100)
print('\\nGrid mean colors (32x24 tiles represented RGB hex)')
for y in range(0,h,24): print(y, ' '.join('#%02x%02x%02x'%tuple(im[y:y+24,x:x+32].mean((0,1)).astype(int)) for x in range(0,w,32)))
print('\\nDark occupancy each 12x12')
ch=' .:-=+*#%@'
for y in range(0,h,12): print('%03d'%y,''.join(ch[min(9,int(((R[y:y+12,x:x+12]<50)&(G[y:y+12,x:x+12]<50)&(B[y:y+12,x:x+12]<50)).mean()*10))] for x in range(0,w,12)))
PY
python .tmp/analyze.py"

